class Solution {
public:
    int lengthOfLIS(std::vector<int>& nums, int k) {
        int max_v = 0;
        for (int x : nums) max_v = std::max(max_v, x);
        std::vector<int> tree(4 * (max_v + 1), 0);

        std::function<int(int, int, int, int, int)> query = [&](int node, int l, int r, int ql, int qr) {
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) / 2;
            int res = 0;
            if (ql <= mid) res = std::max(res, query(2 * node, l, mid, ql, qr));
            if (qr > mid) res = std::max(res, query(2 * node + 1, mid + 1, r, ql, qr));
            return res;
        };

        std::function<void(int, int, int, int, int)> update = [&](int node, int l, int r, int idx, int val) {
            if (l == r) {
                tree[node] = std::max(tree[node], val);
                return;
            }
            int mid = (l + r) / 2;
            if (idx <= mid) update(2 * node, l, mid, idx, val);
            else update(2 * node + 1, mid + 1, r, idx, val);
            tree[node] = std::max(tree[2 * node], tree[2 * node + 1]);
        };

        int ans = 0;
        for (int x : nums) {
            int ql = std::max(1, x - k), qr = x - 1;
            int best = (ql <= qr) ? query(1, 1, max_v, ql, qr) : 0;
            int cur = best + 1;
            update(1, 1, max_v, x, cur);
            ans = std::max(ans, cur);
        }
        return ans;
    }
};

class Solution {
    private int[] tree;

    public int lengthOfLIS(int[] nums, int k) {
        int maxV = 0;
        for (int x : nums) maxV = Math.max(maxV, x);
        tree = new int[4 * (maxV + 1)];

        int ans = 0;
        for (int x : nums) {
            int ql = Math.max(1, x - k), qr = x - 1;
            int best = (ql <= qr) ? query(1, 1, maxV, ql, qr) : 0;
            int cur = best + 1;
            update(1, 1, maxV, x, cur);
            ans = Math.max(ans, cur);
        }
        return ans;
    }

    private int query(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return tree[node];
        int mid = (l + r) / 2;
        int res = 0;
        if (ql <= mid) res = Math.max(res, query(2 * node, l, mid, ql, qr));
        if (qr > mid) res = Math.max(res, query(2 * node + 1, mid + 1, r, ql, qr));
        return res;
    }

    private void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            tree[node] = Math.max(tree[node], val);
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }
}

var lengthOfLIS = function(nums, k) {
    let maxV = 0;
    for (const x of nums) maxV = Math.max(maxV, x);
    const tree = new Array(4 * (maxV + 1)).fill(0);

    function query(node, l, r, ql, qr) {
        if (ql <= l && r <= qr) return tree[node];
        const mid = Math.floor((l + r) / 2);
        let res = 0;
        if (ql <= mid) res = Math.max(res, query(2 * node, l, mid, ql, qr));
        if (qr > mid) res = Math.max(res, query(2 * node + 1, mid + 1, r, ql, qr));
        return res;
    }

    function update(node, l, r, idx, val) {
        if (l === r) {
            tree[node] = Math.max(tree[node], val);
            return;
        }
        const mid = Math.floor((l + r) / 2);
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }

    let ans = 0;
    for (const x of nums) {
        const ql = Math.max(1, x - k), qr = x - 1;
        const best = (ql <= qr) ? query(1, 1, maxV, ql, qr) : 0;
        const cur = best + 1;
        update(1, 1, maxV, x, cur);
        ans = Math.max(ans, cur);
    }
    return ans;
};
